untIn = 1; // ETH\nconst reserveIn = 100; // ETH\nconst reserveOut = 200000; // USDT\n\n// \u8ba1\u7b97\u8f93\u51fa\uff08\u6263\u9664 0.3% \u624b\u7eed\u8d39\uff09\nconst amountInWithFee = amountIn * 997;\nconst numerator = amountInWithFee * reserveOut;\nconst denominator = reserveIn * 1000 + amountInWithFee;\nconst amountOut = numerator / denominator;\n// amountOut \u2248 1980.2 USDT\n\n// \u4ea4\u6613\u540e\u7684\u65b0\u50a8\u5907\nconst newReserveIn = 101; // ETH\nconst newReserveOut = 198019.8; // USDT\n// \u9a8c\u8bc1\uff1a101 * 198019.8 \u2248 20,000,000 \u2713\n"})}),"\n",(0,r.jsx)(e.p,{children:(0,r.jsx)(e.strong,{children:"2. Flash Swaps\uff08\u95ea\u7535\u4ea4\u6362\uff09"})}),"\n",(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{className:"language-solidity",children:"// Uniswap V2 \u72ec\u7279\u529f\u80fd\uff1a\u5148\u83b7\u5f97\u4ee3\u5e01\uff0c\u540e\u4ed8\u6b3e\ninterface IUniswapV2Callee {\n    function uniswapV2Call(\n        address sender,\n        uint amount0,\n        uint amount1,\n        bytes calldata data\n    ) external;\n}\n\n// \u4f7f\u7528\u573a\u666f\uff1a\n// 1. \u95ea\u7535\u8d37\u5957\u5229\n// 2. \u65e0\u9700\u62b5\u62bc\u7684\u4ee3\u5e01\u4ea4\u6362\n// 3. \u6e05\u7b97\u64cd\u4f5c\n"})}),"\n",(0,r.jsx)(e.p,{children:(0,r.jsx)(e.strong,{children:"3. \u4ef7\u683c\u9884\u8a00\u673a\uff08TWAP - Time Weighted Average Price\uff09"})}),"\n",(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{className:"language-solidity",children:"// Uniswap V2 \u5185\u7f6e\u4ef7\u683c\u7d2f\u52a0\u5668\nuint public price0CumulativeLast;\nuint public price1CumulativeLast;\nuint32 public blockTimestampLast;\n\n// \u8ba1\u7b97 TWAP\nfunction currentCumulativePrice() public view returns (uint) {\n    uint32 blockTimestamp = uint32(block.timestamp % 2**32);\n    uint32 timeElapsed = blockTimestamp - blockTimestampLast;\n\n    // \u4ef7\u683c\u7d2f\u52a0\n    return price0CumulativeLast + (reserve1 / reserve0) * timeElapsed;\n}\n\n// \u5916\u90e8\u5408\u7ea6\u4f7f\u7528 TWAP \u83b7\u53d6\u5b89\u5168\u4ef7\u683c\nuint priceAverage = (priceCumulativeEnd - priceCumulativeStart) / timeElapsed;\n"})}),"\n",(0,r.jsx)(e.p,{children:(0,r.jsx)(e.strong,{children:"Uniswap V2 \u8be6\u7ec6\u4f7f\u7528\u793a\u4f8b"})}),"\n",(0,r.jsx)(e.p,{children:(0,r.jsx)(e.strong,{children:"\u5b8c\u6574\u7684 Swap \u6d41\u7a0b\uff08Ethereum \u4e3b\u7f51\uff09"})}),"\n",(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{className:"language-typescript",children:'// 1. \u5b89\u88c5\u4f9d\u8d56\n// npm install @uniswap/sdk @uniswap/v2-core @uniswap/v2-periphery ethers\n\nimport {\n  ChainId,\n  Fetcher,\n  Percent,\n  Route,\n  Token,\n  TokenAmount,\n  Trade,\n  TradeType,\n  WETH,\n} from "@uniswap/sdk";\nimport { ethers } from "ethers";\n\n// 2. \u914d\u7f6e\u63d0\u4f9b\u8005\u548c\u94b1\u5305\nconst provider = new ethers.providers.JsonRpcProvider(\n  "https://eth-mainnet.g.alchemy.com/v2/YOUR_KEY"\n);\nconst wallet = new ethers.Wallet("YOUR_PRIVATE_KEY", provider);\n\n// 3. \u5b9a\u4e49\u4ee3\u5e01\nconst USDC = new Token(\n  ChainId.MAINNET,\n  "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",\n  6,\n  "USDC",\n  "USD Coin"\n);\nconst DAI = new Token(\n  ChainId.MAINNET,\n  "0x6B175474E89094C44Da98b954EedeAC495271d0F",\n  18,\n  "DAI",\n  "Dai Stablecoin"\n);\n\n// 4. \u83b7\u53d6\u4ea4\u6613\u5bf9\u6570\u636e\nconst pair = await Fetcher.fetchPairData(USDC, DAI, provider);\nconsole.log("Reserve USDC:", pair.reserveOf(USDC).toSignificant(6));\nconsole.log("Reserve DAI:", pair.reserveOf(DAI).toSignificant(6));\n\n// 5. \u521b\u5efa\u8def\u5f84\u548c\u4ea4\u6613\nconst route = new Route([pair], USDC); // \u4ece USDC \u5f00\u59cb\nconst amountIn = "1000"; // 1000 USDC\nconst trade = new Trade(\n  route,\n  new TokenAmount(USDC, ethers.utils.parseUnits(amountIn, 6).toString()),\n  TradeType.EXACT_INPUT\n);\n\n// 6. \u67e5\u770b\u4ea4\u6613\u8be6\u60c5\nconsole.log("\u6267\u884c\u4ef7\u683c:", trade.executionPrice.toSignificant(6), "DAI/USDC");\nconsole.log("\u4e2d\u95f4\u4ef7\u683c:", trade.route.midPrice.toSignificant(6), "DAI/USDC");\nconsole.log("\u4ef7\u683c\u5f71\u54cd:", trade.priceImpact.toSignificant(2), "%");\nconsole.log("\u9884\u671f\u8f93\u51fa:", trade.outputAmount.toSignificant(6), "DAI");\n\n// 7. \u8bbe\u7f6e\u6ed1\u70b9\u5bb9\u5fcd\u5ea6\nconst slippageTolerance = new Percent("50", "10000"); // 0.5%\nconst amountOutMin = trade.minimumAmountOut(slippageTolerance);\nconsole.log("\u6700\u5c0f\u8f93\u51fa:", amountOutMin.toSignificant(6), "DAI");\n\n// 8. \u8bbe\u7f6e\u622a\u6b62\u65f6\u95f4\nconst deadline = Math.floor(Date.now() / 1000) + 60 * 20; // 20 \u5206\u949f\n\n// 9. \u6784\u5efa\u4ea4\u6613\u53c2\u6570\nconst path = [USDC.address, DAI.address];\nconst to = wallet.address;\nconst value = "0x0"; // \u4e0d\u662f ETH \u4ea4\u6613\n\n// 10. \u8c03\u7528 Router \u5408\u7ea6\nconst UNISWAP_V2_ROUTER = "0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D";\nconst routerAbi = [\n  "function swapExactTokensForTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external returns (uint[] memory amounts)",\n];\nconst router = new ethers.Contract(UNISWAP_V2_ROUTER, routerAbi, wallet);\n\n// 11. \u5148\u6388\u6743 USDC\nconst usdcContract = new ethers.Contract(\n  USDC.address,\n  ["function approve(address spender, uint256 amount) external returns (bool)"],\n  wallet\n);\nconst approveTx = await usdcContract.approve(\n  UNISWAP_V2_ROUTER,\n  ethers.constants.MaxUint256\n);\nawait approveTx.wait();\n\n// 12. \u6267\u884c\u4ea4\u6362\nconst swapTx = await router.swapExactTokensForTokens(\n  ethers.utils.parseUnits(amountIn, 6), // amountIn\n  amountOutMin.raw.toString(), // amountOutMin\n  path,\n  to,\n  deadline\n);\n\nconst receipt = await swapTx.wait();\nconsole.log("\u4ea4\u6613\u6210\u529f:", receipt.transactionHash);\n'})}),"\n",(0,r.jsx)(e.p,{children:(0,r.jsx)(e.strong,{children:"\u591a\u8df3\u4ea4\u6613\uff08Multi-hop Swap\uff09"})}),"\n",(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{cla